const raw = $input.first().json;
const instruction = raw.instruction || raw.message || '';
const mcpSkills = raw.mcp_skills || '';
const lang = raw.language || 'German';
const lastRun = raw.last_run || null;

const now = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin', dateStyle: 'full', timeStyle: 'short' });

let timeContext = '';
if (lastRun) {
  const lastRunDate = new Date(lastRun);
  const lastRunStr = lastRunDate.toLocaleString('de-DE', { timeZone: 'Europe/Berlin', dateStyle: 'full', timeStyle: 'short' });
  timeContext = `\nIMPORTANT: Your last check was at ${lastRunStr}. ONLY report things that happened or arrived AFTER this time. Anything from before that time has already been reported — ignore it completely.\nIf there is nothing new since ${lastRunStr}, respond [SILENT].`;
} else {
  timeContext = `\nThis is the FIRST check. Report current state briefly if there is anything noteworthy.`;
}

const systemPrompt = `# BACKGROUND CHECKER
Current time: ${now}

You are a background checker executing a scheduled task silently.
Execute the instruction below using the available tools.
${timeContext}

RULES:
- ONLY use the tool(s) needed for the instruction. The instruction tells you which tool to use.
- Do NOT call tools on unrelated MCP servers. Do NOT explore or discover all available tools.
- Call the MCP Client ONCE with the correct server URL and tool name from the list below.
- NEVER send messages yourself (no Telegram, no notifications). Just return your findings as text.
- If the result shows something NEW (after your last check), describe it concisely in ${lang}.
- If there is NOTHING new or changed to report, respond with ONLY the exact text: [SILENT]
- Do NOT add greetings, commentary, or explanations when responding [SILENT].
- Ignore any part of the instruction that asks you to send notifications or messages — just report findings.
- Be concise when reporting changes — just the facts.
- Maximum 3 tool calls total. If you cannot complete the task in 3 calls, respond [SILENT].

${mcpSkills ? '# AVAILABLE MCP SKILLS (reference only — use ONLY what the instruction needs)\n' + mcpSkills : ''}`;

return [{
  json: {
    systemPrompt,
    userMessage: instruction
  }
}];

const qType = typeof query;
let url = '', method = 'GET', headers = {}, body = null;

if (qType === 'object' && query !== null) {
  url = query.url || '';
  method = (query.method || 'GET').toUpperCase();
  headers = query.headers || {};
  body = query.body || null;
} else if (qType === 'string') {
  try {
    const parsed = JSON.parse(query);
    url = parsed.url || '';
    method = (parsed.method || 'GET').toUpperCase();
    headers = parsed.headers || {};
    body = parsed.body || null;
  } catch(e) {
    url = query;
  }
}

if (!url) return 'Error: no URL provided';

try {
  const opts = { method, url, headers };
  if (body && method !== 'GET') {
    opts.body = typeof body === 'string' ? body : JSON.stringify(body);
    if (!headers['Content-Type']) headers['Content-Type'] = 'application/json';
  }
  const resp = await helpers.httpRequest(opts);
  const result = typeof resp === 'string' ? resp : JSON.stringify(resp);
  return result.length > 10000 ? result.substring(0, 10000) + '... (truncated)' : result;
} catch(e) {
  return 'HTTP Error: ' + e.message;
}

let input;
try { input = JSON.parse(query); } catch(e) { input = { q: query }; }
const q = input.q || input.query || query;
const result = await helpers.httpRequest({
  method: 'GET',
  url: `http://searxng:8080/search?q=${encodeURIComponent(q)}&format=json&language=de`,
  headers: { 'Accept': 'application/json' }
});
const hits = (result.results || []).slice(0, 5).map(r =>
  `${r.title}\n${r.url}\n${r.content || ''}`
).join('\n\n');
return hits || 'Keine Ergebnisse gefunden.';

const qType = typeof query;
let mcpUrl = '', toolName = '', args = {};

if (qType === 'object' && query !== null) {
  mcpUrl = query.mcp_url || '';
  toolName = query.tool_name || '';
  args = query.arguments || {};
} else if (qType === 'string') {
  try {
    const parsed = JSON.parse(query);
    mcpUrl = parsed.mcp_url || '';
    toolName = parsed.tool_name || '';
    args = parsed.arguments || {};
  } catch(e) {
    return 'Parse error: query=' + String(query).substring(0,200) + ' type=' + qType;
  }
} else {
  return 'Unexpected query type: ' + qType + ' value: ' + String(query).substring(0,200);
}

if (typeof args === 'string') try { args = JSON.parse(args); } catch(e) {}

// ---- Audit-Log: wer hat welches Werkzeug womit aufgerufen (best effort) ----
// Skills melden nur ihr Ergebnis ("Page created [id: 123]"), nie ihre Eingabe.
// Ohne diesen Block laesst sich im Nachhinein nicht rekonstruieren, WAS
// geschrieben wurde. Stoert das Werkzeug nie: alles in try/catch, 4s Timeout.
const _t0 = Date.now();
const _SECRET_KEY_RE = /(pass|pwd|secret|token|key|auth|credential|cookie|session|otp|pin|signature|bearer|apikey)/i;
const _SECRET_VAL_RE = /^(sk-|sk_live|ghp_|gho_|github_pat_|xox[baprs]-|Bearer\s|eyJ[A-Za-z0-9_-]{10,}\.)/;
function _mask(v, d) {
  if (d > 4) return '[deep]';
  if (Array.isArray(v)) return v.slice(0, 20).map(x => _mask(x, d + 1));
  if (v && typeof v === 'object') {
    const o = {};
    for (const k of Object.keys(v).slice(0, 40)) o[k] = _SECRET_KEY_RE.test(k) ? '[redacted]' : _mask(v[k], d + 1);
    return o;
  }
  if (typeof v === 'string') {
    if (_SECRET_VAL_RE.test(v)) return '[redacted]';
    return v.length > 500 ? v.slice(0, 500) + '...[' + v.length + ' chars]' : v;
  }
  return v;
}
let _safeArgs = _mask(args, 0);
let _argsTruncated = false;
try {
  const _s = JSON.stringify(_safeArgs);
  if (_s && _s.length > 8000) { _safeArgs = { _truncated: _s.slice(0, 8000) }; _argsTruncated = true; }
} catch (_e) { _safeArgs = { _unserializable: true }; _argsTruncated = true; }
// Schreibend oder lesend: Namensmuster als Fallback, echte MCP-Annotations
// (readOnlyHint/destructiveHint) gewinnen weiter unten, sobald tools/list da ist.
const _WRITE_RE = /(^|[_\-.])(create|add|insert|new|update|edit|patch|set|modify|change|delete|remove|drop|archive|send|post|publish|upload|write|put|move|rename|assign|transition|close|complete|resolve|approve|reject|cancel|schedule|book|order|pay|invite|revoke|reset|import)([_\-.]|$)/i;
let _isWrite = _WRITE_RE.test(toolName);
let _writeSource = 'heuristic';
async function _audit(_status, _text) {
  try {
    let _sid = null, _uid = null, _src = null, _exec = null;
    try { _exec = String($execution.id); } catch (_e) {}
    await helpers.httpRequest({
      method: 'POST',
      url: '{{SUPABASE_URL}}/rest/v1/tool_audit_log',
      headers: { 'apikey': '{{SUPABASE_SERVICE_KEY}}', 'Authorization': 'Bearer {{SUPABASE_SERVICE_KEY}}', 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
      body: JSON.stringify({
        session_id: _sid, user_id: _uid, source: _src, origin: 'background',
        server_url: mcpUrl, tool_name: toolName,
        is_write: _isWrite, write_source: _writeSource,
        args: _safeArgs, args_truncated: _argsTruncated,
        status: _status,
        result_summary: _status === 'ok' ? String(_text).substring(0, 500) : null,
        error: _status === 'ok' ? null : String(_text).substring(0, 500),
        duration_ms: Date.now() - _t0,
        execution_id: _exec
      }),
      timeout: 4000
    });
  } catch (_e) {}
  return _text;
}
if (!mcpUrl || !toolName) return 'Fehler: mcp_url=' + mcpUrl + ' tool_name=' + toolName;

function parseSSE(raw) {
  const str = String(raw);
  let lines = str.split('\n');
  if (lines.length <= 1) lines = str.split('\\n');
  for (let i = lines.length - 1; i >= 0; i--) {
    if (lines[i].startsWith('data: ')) {
      return JSON.parse(lines[i].substring(6));
    }
  }
  return null;
}

try {
  let authHeader = null;
  try {
    const row = await helpers.httpRequest({method:'GET',url:'{{SUPABASE_URL}}/rest/v1/mcp_registry?mcp_url=eq.'+encodeURIComponent(mcpUrl)+'&select=auth_type,auth_token&limit=1',headers:{apikey:'{{SUPABASE_SERVICE_KEY}}',Authorization:'Bearer {{SUPABASE_SERVICE_KEY}}'},json:true});
    if (row && row[0] && row[0].auth_type && row[0].auth_type !== 'none' && row[0].auth_token) {
      authHeader = row[0].auth_type === 'bearer' ? 'Bearer '+row[0].auth_token : row[0].auth_token;
    }
  } catch(e) {}

  const hdrs = {'Content-Type':'application/json','Accept':'application/json, text/event-stream'};
  if (authHeader) hdrs['Authorization'] = authHeader;

  const init = await helpers.httpRequest({
    method: 'POST', url: mcpUrl,
    headers: hdrs,
    body: JSON.stringify({jsonrpc:'2.0',id:1,method:'initialize',params:{protocolVersion:'2024-11-05',capabilities:{},clientInfo:{name:'n8n-claw-bg-checker',version:'1.0'}}}),
    returnFullResponse: true, encoding: 'utf-8', json: false
  });
  const sid = init.headers && init.headers['mcp-session-id'];
  if (sid) hdrs['mcp-session-id'] = sid;

  await helpers.httpRequest({
    method: 'POST', url: mcpUrl,
    headers: hdrs,
    body: JSON.stringify({jsonrpc:'2.0',method:'notifications/initialized'}),
    json: false
  });

  const listResp = await helpers.httpRequest({
    method: 'POST', url: mcpUrl,
    headers: hdrs,
    body: JSON.stringify({jsonrpc:'2.0',id:2,method:'tools/list',params:{}}),
    json: false
  });
  const listResult = parseSSE(listResp);
  let toolSchema = null;
  if (listResult && listResult.result && listResult.result.tools) {
    const tool = listResult.result.tools.find(t => t.name === toolName);
    if (tool && tool.inputSchema) toolSchema = tool.inputSchema;
    // MCP-Annotations sind die einzige autoritative Quelle dafuer, ob ein Tool
    // schreibt - sie kommen vom Server selbst und kosten keinen Extra-Request.
    if (tool && tool.annotations) {
      const _a = tool.annotations;
      if (typeof _a.readOnlyHint === 'boolean') { _isWrite = !_a.readOnlyHint; _writeSource = 'annotation'; }
      else if (_a.destructiveHint === true) { _isWrite = true; _writeSource = 'annotation'; }
    }
  }

  function schemaHint(problem) {
    if (!toolSchema) return null;
    return 'Tool "' + toolName + '" call rejected: ' + problem +
      '\n\nCorrect input schema:\n' + JSON.stringify(toolSchema, null, 2) +
      '\n\nRetry the tool call with parameter names matching this schema exactly.';
  }

  if (toolSchema && toolSchema.properties) {
    const allowed = Object.keys(toolSchema.properties);
    const required = toolSchema.required || [];
    const unknown = Object.keys(args).filter(k => !allowed.includes(k));
    // Sub-Agenten und die Hintergrundpruefung kennen die fragende Person nicht.
    // caller bleibt deshalb leer, und Werkzeuge mit persoenlichen Zugaengen
    // antworten mit "kein Konto verbunden", statt im Namen einer falschen Person
    // zu handeln. Das ist der sichere Ausgang, nicht der bequeme.
    if (allowed.includes('caller')) {
      args.caller = '';
      // Protokoll-Schnappschuss erneuern, siehe Agent-Fassung.
      try { _safeArgs = _mask(args, 0); } catch (_e) {}
    }
    // n8n veroeffentlicht JEDES deklarierte Feld eines toolWorkflow-Tools als
    // required, auch die ausdruecklich optionalen. Ein fehlendes Feld deshalb
    // nicht abweisen, sondern leer nachfuellen - genau das tut n8n bei den
    // eigenen Tool-Nodes ebenfalls. Die Skills pruefen ihre echten Pflichtfelder
    // selbst und melden sie klar. Vorher kostete jeder erste Aufruf eines Tools
    // mit optionalen Parametern eine Ablehnung plus Neuversuch des Modells.
    // Typ angleichen, bevor n8n validiert: das Modell schickt natuerlicherweise
    // Zahlen (expected_version: 21, limit: 50), das veroeffentlichte Schema
    // verlangt Strings. Die Ablehnung kostet sonst eine komplette LLM-Runde und
    // war im Testphasen-Report das haeufigste wiederkehrende Fehlermuster.
    for (const k of Object.keys(args)) {
      const spec = toolSchema.properties[k];
      if (!spec || spec.type !== 'string') continue;
      const v = args[k];
      if (typeof v === 'number' || typeof v === 'boolean') args[k] = String(v);
      // Arrays und Objekte als JSON serialisieren: Modelle schicken cells als
      // echtes Array, das Schema verlangt aber einen String, und die Skills
      // parsen ihn ohnehin wieder. Ohne das kostet jeder erste Aufruf eine Runde.
      else if (v !== null && typeof v === 'object') { try { args[k] = JSON.stringify(v); } catch (_e) {} }
    }
    for (const r of required) {
      if (args[r] !== undefined && args[r] !== null) continue;
      const t = (toolSchema.properties[r] || {}).type;
      if (t === undefined || t === 'string') args[r] = '';
    }
    if (unknown.length > 0) {
      const problems = [];
      problems.push('unknown args [' + unknown.join(', ') + ']');
      return await _audit('rejected', schemaHint(problems.join('; ')) || ('Tool "' + toolName + '" call rejected: ' + problems.join('; ')));
    }
  }

  const resp = await helpers.httpRequest({
    method: 'POST', url: mcpUrl,
    headers: hdrs,
    body: JSON.stringify({jsonrpc:'2.0',id:3,method:'tools/call',params:{name:toolName,arguments:args}}),
    returnFullResponse: true, encoding: 'utf-8', json: false
  });

  const result = parseSSE(resp.body || resp);
  if (!result) return await _audit('error', 'MCP: Keine Daten. Response: ' + String(resp.body || resp).substring(0,500));
  if (result.error) {
    return await _audit('error', schemaHint('server error: ' + JSON.stringify(result.error)) || ('MCP Error: ' + JSON.stringify(result.error)));
  }
  if (result.result && result.result.isError) {
    const errText = (result.result.content && result.result.content[0] && result.result.content[0].text) || JSON.stringify(result.result);
    return await _audit('error', schemaHint('tool returned error: ' + errText) || ('MCP Tool Error: ' + errText));
  }
  return await _audit('ok', result.result?.content?.[0]?.text || JSON.stringify(result.result));
} catch(e) {
  return await _audit('error', 'MCP Error: ' + e.message);
}

let input;
try { input = JSON.parse(query); } catch(e) { input = { url: query }; }
if (!input.url) return 'Error: url is required';
try {
  const resp = await helpers.httpRequest({
    method: 'POST',
    url: 'http://crawl4ai:11235/crawl',
    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer {{CRAWL4AI_API_TOKEN}}' },
    body: JSON.stringify({ urls: [input.url], crawler_config: { type: 'CrawlerRunConfig', params: { stream: false, cache_mode: 'bypass' } } }),
    timeout: 30000
  });
  const results = resp.results || resp;
  const result = Array.isArray(results) ? results[0] : results;
  if (!result.success) return 'Error: ' + (result.error_message || 'Crawl failed');
  const mdObj = result.markdown || {};
  const md = typeof mdObj === 'string' ? mdObj : (mdObj.raw_markdown || '');
  return md.substring(0, 8000);
} catch(e) {
  return 'Error fetching page: ' + e.message;
}

const agentOutput = $('Checker Agent').first().json.output || '';
const isSilent = agentOutput.includes('[SILENT]');

return [{
  json: {
    notify: !isSilent,
    message: isSilent ? '' : agentOutput
  }
}];
